package com.crm.hr.service;import com.crm.hr.dto.LeaveQuotaRequest;import com.crm.hr.entity.LeaveQuota;import com.crm.hr.repository.LeaveQuotaRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Service @Transactional public class LeaveQuotaService{private final LeaveQuotaRepository repository;private final EmployeeReferenceValidator employees;public LeaveQuotaService(LeaveQuotaRepository r,EmployeeReferenceValidator e){repository=r;employees=e;}@Transactional(readOnly=true)public List<LeaveQuota> list(String employeeId,String authorization){employees.requireExists(employeeId,authorization);return repository.findAllByEmployeeIdOrderByPeriodStartDesc(employeeId);}public LeaveQuota assign(LeaveQuotaRequest r,String authorization){if(r.periodEnd().isBefore(r.periodStart()))throw new IllegalArgumentException("Quota period end precedes start");employees.requireExists(r.employeeId(),authorization);LeaveQuota q=new LeaveQuota();q.setEmployeeId(r.employeeId());q.setPeriodStart(r.periodStart());q.setPeriodEnd(r.periodEnd());q.setLeaveType(r.leaveType().trim());q.setGrantedDays(r.grantedDays());return repository.save(q);}public void delete(long id){repository.deleteById(id);}}
